-- ==============================================================================
-- THE BOYS — 3D AI GENERATION & PERSONALIZED PHYSICAL PRINTING PLATFORM
-- CONSOLIDATED 6-TABLE PRODUCTION DATABASE SCHEMA (SQL SERVER / T-SQL)
-- Generated by Data Analysis & Database Architect Skill (gemini-code-1792395197211)
-- Consolidation:
--   1. UserCredits merged into Users
--   2. ModelAssets merged into GenerationTasks
--   3. Defect reports & status milestones merged into Orders
--   4. OutboxMessages removed
-- Standards: 3NF/BCNF, Historical Financial Snapshots, ESR Indexes, Soft-Delete
-- ==============================================================================

USE master;
GO

IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = N'TheBoysDb')
BEGIN
    CREATE DATABASE TheBoysDb COLLATE Latin1_General_100_CI_AS_SC_UTF8;
END
GO

USE TheBoysDb;
GO

-- ==============================================================================
-- BẢNG 1: Users (Đã gộp UserCredits: Quota dùng thử 2 lượt theo CP3)
-- ==============================================================================
CREATE TABLE Users (
    Id UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_Users PRIMARY KEY DEFAULT NEWSEQUENTIALID(),
    Email NVARCHAR(255) NOT NULL,
    PasswordHash NVARCHAR(500) NULL, -- NULL nếu đăng nhập qua Google OAuth
    FullName NVARCHAR(150) NOT NULL,
    PhoneNumber VARCHAR(20) NULL,
    Role INT NOT NULL CONSTRAINT DF_Users_Role DEFAULT (0), -- 0: Customer, 1: PartnerLab, 2: Operator, 3: Admin
    DeviceFingerprint VARCHAR(100) NULL, -- Chống tạo clone account vét credit
    IsPhoneVerified BIT NOT NULL CONSTRAINT DF_Users_IsPhoneVerified DEFAULT (0),
    
    -- Gộp từ UserCredits (Định mức 2 lượt tạo AI miễn phí theo CP3)
    FreeTrialRemaining INT NOT NULL CONSTRAINT DF_Users_FreeTrial DEFAULT (2),
    PurchasedRemaining INT NOT NULL CONSTRAINT DF_Users_Purchased DEFAULT (0),
    TotalUsed INT NOT NULL CONSTRAINT DF_Users_TotalUsed DEFAULT (0),

    CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_Users_CreatedAtUtc DEFAULT SYSUTCDATETIME(),
    UpdatedAtUtc DATETIME2(3) NULL,
    IsDeleted BIT NOT NULL CONSTRAINT DF_Users_IsDeleted DEFAULT (0),
    DeletedAtUtc DATETIME2(3) NULL,
    RowVersion ROWVERSION NOT NULL,

    CONSTRAINT CK_Users_CreditsNonNegative CHECK (FreeTrialRemaining >= 0 AND PurchasedRemaining >= 0 AND TotalUsed >= 0)
);

-- Index Email duy nhất có điều kiện Soft-Delete
CREATE UNIQUE NONCLUSTERED INDEX UX_Users_Email_Active
    ON Users (Email)
    WHERE IsDeleted = 0;

-- Index định danh thiết bị kiểm soát gian lận
CREATE NONCLUSTERED INDEX IX_Users_DeviceFingerprint
    ON Users (DeviceFingerprint)
    WHERE DeviceFingerprint IS NOT NULL AND IsDeleted = 0;


-- ==============================================================================
-- BẢNG 2: PricingPackages (Danh mục gói thành phẩm cá nhân hóa: 300k, 390k)
-- ==============================================================================
CREATE TABLE PricingPackages (
    Id UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_PricingPackages PRIMARY KEY DEFAULT NEWSEQUENTIALID(),
    PackageCode VARCHAR(50) NOT NULL, -- 'TIER_STANDARD_390', 'TIER_BASELINE_300'
    Name NVARCHAR(150) NOT NULL,
    PriceVnd DECIMAL(18, 2) NOT NULL, -- 390.000 hoặc 300.000 VNĐ
    PartnerBaseCostVnd DECIMAL(18, 2) NOT NULL CONSTRAINT DF_PricingPackages_PartnerCost DEFAULT (120000.00), -- Chi phí xưởng 120k theo CP3
    Material NVARCHAR(50) NOT NULL, -- 'Resin 16K', 'PLA'
    HeightRangeCm NVARCHAR(50) NOT NULL, -- '10 - 12 cm', '7 - 8 cm'
    Description NVARCHAR(500) NULL,
    IsActive BIT NOT NULL CONSTRAINT DF_PricingPackages_IsActive DEFAULT (1),
    CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_PricingPackages_CreatedAt DEFAULT SYSUTCDATETIME(),

    CONSTRAINT CK_PricingPackages_Metrics CHECK (PriceVnd > 0 AND PartnerBaseCostVnd >= 0)
);

CREATE UNIQUE NONCLUSTERED INDEX UX_PricingPackages_Code ON PricingPackages(PackageCode);


-- ==============================================================================
-- BẢNG 3: PartnerLabs (Xưởng in 3D đối tác TP.HCM)
-- ==============================================================================
CREATE TABLE PartnerLabs (
    Id UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_PartnerLabs PRIMARY KEY DEFAULT NEWSEQUENTIALID(),
    UserId UNIQUEIDENTIFIER NULL, -- Liên kết tài khoản đăng nhập portal nếu có
    LabName NVARCHAR(200) NOT NULL,
    ContactPerson NVARCHAR(100) NOT NULL,
    PhoneNumber VARCHAR(20) NOT NULL,
    Email NVARCHAR(255) NULL,
    District NVARCHAR(100) NOT NULL, -- 'Quận 10', 'Bình Thạnh', 'TP. Thủ Đức'
    Address NVARCHAR(300) NOT NULL,
    CapacityPerDay INT NOT NULL CONSTRAINT DF_PartnerLabs_Capacity DEFAULT (20),
    IsActive BIT NOT NULL CONSTRAINT DF_PartnerLabs_IsActive DEFAULT (1),
    CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_PartnerLabs_CreatedAt DEFAULT SYSUTCDATETIME(),

    CONSTRAINT FK_PartnerLabs_Users FOREIGN KEY (UserId)
        REFERENCES Users (Id) ON DELETE SET NULL
);


-- ==============================================================================
-- BẢNG 4: GenerationTasks (Đã gộp ModelAssets: Quản lý tác vụ AI & Dữ liệu file 3D)
-- ==============================================================================
CREATE TABLE GenerationTasks (
    Id UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_GenerationTasks PRIMARY KEY DEFAULT NEWSEQUENTIALID(),
    UserId UNIQUEIDENTIFIER NOT NULL,
    TaskType INT NOT NULL, -- 0: TextTo3D, 1: ImageTo3D
    Prompt NVARCHAR(1000) NULL,
    ArtStyle NVARCHAR(50) NULL,
    InputImageUrl NVARCHAR(1000) NULL,
    CleanedImageUrl NVARCHAR(1000) NULL,
    Status INT NOT NULL CONSTRAINT DF_GenerationTasks_Status DEFAULT (0), -- 0: Queued, 1: Processing, 2: MeshOptimizing, 3: Succeeded, 4: Failed, 5: Expired
    ProviderTaskId VARCHAR(150) NULL, -- ID trả về từ Meshy AI
    ErrorMessage NVARCHAR(1000) NULL,
    RetryCount INT NOT NULL CONSTRAINT DF_GenerationTasks_RetryCount DEFAULT (0),
    DurationSeconds INT NULL,

    -- Gộp từ ModelAssets: Thông số hình học 3D & đường dẫn lưu trữ
    ModelName NVARCHAR(200) NULL,
    StoragePathGlb NVARCHAR(1000) NULL, -- File Three.js Web Viewer
    StoragePathStl NVARCHAR(1000) NULL, -- File Watertight gửi xưởng in 3D
    ThumbnailUrl NVARCHAR(1000) NULL,
    Polycount INT NULL,
    VertexCount INT NULL,
    IsWatertight BIT NOT NULL CONSTRAINT DF_GenerationTasks_IsWatertight DEFAULT (0),
    MinWallThicknessMm DECIMAL(5, 2) NULL,
    BoundingBoxX_Mm DECIMAL(8, 2) NULL,
    BoundingBoxY_Mm DECIMAL(8, 2) NULL,
    BoundingBoxZ_Mm DECIMAL(8, 2) NULL,
    EstimatedVolumeCm3 DECIMAL(8, 2) NULL,
    IsApprovedForPrinting BIT NOT NULL CONSTRAINT DF_GenerationTasks_IsApproved DEFAULT (0),

    CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_GenerationTasks_CreatedAt DEFAULT SYSUTCDATETIME(),
    CompletedAtUtc DATETIME2(3) NULL,
    IsDeleted BIT NOT NULL CONSTRAINT DF_GenerationTasks_IsDeleted DEFAULT (0),
    DeletedAtUtc DATETIME2(3) NULL,
    RowVersion ROWVERSION NOT NULL,

    CONSTRAINT FK_GenerationTasks_Users FOREIGN KEY (UserId)
        REFERENCES Users (Id) ON DELETE NO ACTION,
    CONSTRAINT CK_GenerationTasks_Metrics CHECK (
        (Polycount IS NULL OR Polycount >= 0) AND 
        (VertexCount IS NULL OR VertexCount >= 0)
    )
);

-- ESR Index phục vụ Polling/truy vấn tác vụ của user
CREATE NONCLUSTERED INDEX IX_GenerationTasks_User_Status_ESR
    ON GenerationTasks (UserId, Status, CreatedAtUtc DESC)
    INCLUDE (TaskType, ProviderTaskId);

-- ESR Index phục vụ Thư viện 3D cá nhân (My Library)
CREATE NONCLUSTERED INDEX IX_GenerationTasks_User_Library_ESR
    ON GenerationTasks (UserId, IsApprovedForPrinting, CreatedAtUtc DESC)
    WHERE IsDeleted = 0;


-- ==============================================================================
-- BẢNG 5: Orders (Đã gộp Lỗi in Defect 5% & Mốc thời gian trạng thái Timeline)
-- ==============================================================================
CREATE TABLE Orders (
    Id UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_Orders PRIMARY KEY DEFAULT NEWSEQUENTIALID(),
    OrderCode VARCHAR(50) NOT NULL, -- 'TB-ORD-20261019-0001'
    UserId UNIQUEIDENTIFIER NOT NULL,
    GenerationTaskId UNIQUEIDENTIFIER NOT NULL,
    PricingPackageId UNIQUEIDENTIFIER NOT NULL,
    PartnerLabId UNIQUEIDENTIFIER NULL, -- Phân công cho xưởng in TP.HCM
    Status INT NOT NULL CONSTRAINT DF_Orders_Status DEFAULT (0),
    -- 0: Draft, 1: PendingPayment, 2: Paid, 3: SentToPartner, 4: Printing, 5: Reprinting, 6: PostProcessing, 7: Packaged, 8: Shipping, 9: Delivered, 10: Cancelled, 11: Refunded

    -- Strategic Financial Snapshots (Bảo toàn số liệu P&L theo CP3)
    UnitPriceSnapshot DECIMAL(18, 2) NOT NULL, -- 390.000 hoặc 300.000 VNĐ
    PartnerCostSnapshot DECIMAL(18, 2) NOT NULL, -- 120.000 VNĐ
    AiCostBudgetSnapshot DECIMAL(18, 2) NOT NULL, -- 10.000 VNĐ
    DefectBudgetSnapshot DECIMAL(18, 2) NOT NULL, -- 6.000 VNĐ (5% của giá xưởng)
    ShippingSubsidySnapshot DECIMAL(18, 2) NOT NULL, -- 10.000 VNĐ trợ giá nền tảng
    PaymentGatewayFeeSnapshot DECIMAL(18, 2) NOT NULL, -- 1% giá trị đơn

    Quantity INT NOT NULL CONSTRAINT DF_Orders_Quantity DEFAULT (1),
    SubTotalVnd DECIMAL(18, 2) NOT NULL,
    ShippingFeeRaw DECIMAL(18, 2) NOT NULL,
    FinalShippingFee DECIMAL(18, 2) NOT NULL, -- ShippingFeeRaw - ShippingSubsidySnapshot
    TotalAmount DECIMAL(18, 2) NOT NULL, -- SubTotalVnd + FinalShippingFee

    -- Thông tin giao hàng & khắc tên cá nhân hóa
    CustomEngravingText NVARCHAR(150) NULL,
    ReceiverName NVARCHAR(150) NOT NULL,
    ReceiverPhone VARCHAR(20) NOT NULL,
    StreetAddress NVARCHAR(300) NOT NULL,
    District NVARCHAR(100) NOT NULL,
    City NVARCHAR(100) NOT NULL CONSTRAINT DF_Orders_City DEFAULT (N'Thành phố Hồ Chí Minh'),
    CustomerNote NVARCHAR(500) NULL,
    TrackingNumber VARCHAR(100) NULL,

    -- Gộp từ OrderDefectReports (Quản lý ngân sách xử lý lỗi 5% theo CP3)
    DefectReason NVARCHAR(500) NULL,
    EvidencePhotoUrl NVARCHAR(1000) NULL,
    EstimatedDefectCostVnd DECIMAL(18, 2) NULL CONSTRAINT DF_Orders_DefectCost DEFAULT (6000.00),
    ReprintApproved BIT NOT NULL CONSTRAINT DF_Orders_ReprintApproved DEFAULT (0),

    -- Gộp từ OrderStatusHistories (Dòng thời gian trạng thái đơn hàng - Timeline Milestones)
    CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_Orders_CreatedAt DEFAULT SYSUTCDATETIME(),
    PaidAtUtc DATETIME2(3) NULL,
    SentToPartnerAtUtc DATETIME2(3) NULL,
    PrintingStartedAtUtc DATETIME2(3) NULL,
    PackagedAtUtc DATETIME2(3) NULL,
    ShippedAtUtc DATETIME2(3) NULL,
    DeliveredAtUtc DATETIME2(3) NULL,
    CancelledAtUtc DATETIME2(3) NULL,
    StatusNote NVARCHAR(500) NULL,

    RowVersion ROWVERSION NOT NULL,

    CONSTRAINT FK_Orders_Users FOREIGN KEY (UserId)
        REFERENCES Users (Id) ON DELETE NO ACTION,
    CONSTRAINT FK_Orders_GenerationTasks FOREIGN KEY (GenerationTaskId)
        REFERENCES GenerationTasks (Id) ON DELETE NO ACTION,
    CONSTRAINT FK_Orders_PricingPackages FOREIGN KEY (PricingPackageId)
        REFERENCES PricingPackages (Id) ON DELETE NO ACTION,
    CONSTRAINT FK_Orders_PartnerLabs FOREIGN KEY (PartnerLabId)
        REFERENCES PartnerLabs (Id) ON DELETE NO ACTION,
    CONSTRAINT CK_Orders_Financials CHECK (SubTotalVnd >= 0 AND TotalAmount >= 0 AND Quantity > 0)
);

CREATE UNIQUE NONCLUSTERED INDEX UX_Orders_OrderCode ON Orders(OrderCode);

-- ESR Index phục vụ khách hàng tra cứu danh sách đơn hàng
CREATE NONCLUSTERED INDEX IX_Orders_User_Status_ESR
    ON Orders (UserId, Status, CreatedAtUtc DESC)
    INCLUDE (OrderCode, TotalAmount);

-- ESR Index phục vụ xưởng in lấy hàng đợi sản xuất (First-In First-Out)
CREATE NONCLUSTERED INDEX IX_Orders_Partner_Queue_ESR
    ON Orders (PartnerLabId, Status, CreatedAtUtc ASC)
    WHERE PartnerLabId IS NOT NULL;


-- ==============================================================================
-- BẢNG 6: Payments (Giao dịch cổng thanh toán trực tuyến: MoMo, VNPay, VietQR)
-- ==============================================================================
CREATE TABLE Payments (
    Id UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_Payments PRIMARY KEY DEFAULT NEWSEQUENTIALID(),
    OrderId UNIQUEIDENTIFIER NOT NULL,
    PaymentMethod VARCHAR(50) NOT NULL, -- 'MoMoQR', 'VNPay', 'VietQR_SePay'
    TransactionReference VARCHAR(150) NOT NULL,
    Amount DECIMAL(18, 2) NOT NULL,
    Status INT NOT NULL CONSTRAINT DF_Payments_Status DEFAULT (0), -- 0: Pending, 1: Success, 2: Failed, 3: Expired
    GatewayResponseJson NVARCHAR(MAX) NULL,
    CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_Payments_CreatedAt DEFAULT SYSUTCDATETIME(),
    PaidAtUtc DATETIME2(3) NULL,

    CONSTRAINT FK_Payments_Orders FOREIGN KEY (OrderId)
        REFERENCES Orders (Id) ON DELETE NO ACTION,
    CONSTRAINT CK_Payments_PositiveAmount CHECK (Amount > 0)
);

CREATE NONCLUSTERED INDEX IX_Payments_Order_Status ON Payments (OrderId, Status);
CREATE UNIQUE NONCLUSTERED INDEX UX_Payments_TransactionRef ON Payments (TransactionReference);

GO
